{
  "id": "V007",
  "checks": [
    {
      "field": "purpose",
      "score": 2,
      "reason": "지역별 생활 장면에 맞는 광고 이미지 초안 준비 목적이 보존됨."
    },
    {
      "field": "action",
      "score": 2,
      "reason": "이미지 후보를 만들고 담당자가 검토하는 흐름이 보존됨."
    },
    {
      "field": "object",
      "score": 2,
      "reason": "생활용품 광고 이미지 후보가 보존됨."
    },
    {
      "field": "input",
      "score": 2,
      "reason": "승인된 제품 사진을 입력으로 사용한다는 점이 보존됨."
    },
    {
      "field": "output",
      "score": 2,
      "reason": "제품 외형과 브랜드 표현을 유지하고 배경을 달리한 이미지 후보가 보존됨."
    },
    {
      "field": "constraints",
      "score": 2,
      "reason": "제품 성능 변경과 새 효능 문구 추가 금지, 승인 뒤 게시 조건이 보존됨."
    },
    {
      "field": "no_added_functions",
      "score": 2,
      "reason": "출처에 없는 기능이 추가되지 않음."
    },
    {
      "field": "roles",
      "score": 2,
      "reason": "담당자가 후보를 검토하고 광고 게시가 승인 뒤 진행된다는 역할 흐름이 보존됨."
    }
  ],
  "issues": [],
  "permission_interpretation": "AI가 실제 광고를 게시하거나 승인한다고 명시하지 않으며, 게시 전 승인이 필요하다는 조건만 보존됨."
}
